S.add(new THREE.HemisphereLight(0xfff4dc,0x23407a,1.5));const L=new THREE.DirectionalLight(0xffffff,2);L.position.set(-10,20,25);S.add(L);
const G=(x,m,a,b)=>Math.exp(-Math.pow((x-m)/(x<m?a:b),2));
function H(x,z){ // big left wave (steep on right side), foreground swell, right swell
 let h=15*G(x,-11,9,4.2)*Math.exp(-Math.pow((z+2)/9,2));
 h+=6*G(x,-2,6,12)*Math.exp(-Math.pow((z-9)/5,2));
 h+=8*G(x,26,9,9)*Math.exp(-Math.pow((z+2)/12,2));
 h+=4*G(x,10,8,10)*Math.exp(-Math.pow((z-10)/4,2));
 return h-1.5+.35*Math.sin(x*1.3+z*.9)+.2*Math.sin(x*2.7-z*1.7);}
