for(let i=0;i<pp.count;i+=3){const y=(pp.getY(i)+pp.getY(i+1)+pp.getY(i+2))/3,x=pp.getX(i),z=pp.getZ(i);
 const n=((Math.sin(x*3.1+z*5.3)*43758.5)%1+1)%1;let t=(y+1)/15+n*.12;
 const k=t>.62?4:t>.42?3:t>.22?(n>.5?2:1):(n>.7?2:0);
 for(let j=0;j<3;j++){col.set([cs[k].r,cs[k].g,cs[k].b],(i+j)*3);}}
ng.setAttribute('color',new THREE.BufferAttribute(col,3));
S.add(new THREE.Mesh(ng,new THREE.MeshStandardMaterial({vertexColors:true,flatShading:true,roughness:1})));
// foam claws curling off the crest
const fm=new THREE.MeshStandardMaterial({color:0xf4efe0,flatShading:true,roughness:1}),claws=[];
for(let i=0;i<46;i++){const a=i/45,ang=Math.PI*(.95-a*.95);
 const cx=-11+Math.cos(ang)*9*a+ -1, cy=14+Math.sin(ang)*5+ -a*2.5;
 const m=new THREE.Mesh(new THREE.ConeGeometry(.35+Math.random()*.4,1.8+Math.random()*1.6,4),fm);
 m.position.set(cx+(Math.random()-.5)*1.5,cy+(Math.random()-.5)*1.5,-2+(Math.random()-.5)*5);
 m.rotation.z=-ang-.3+(Math.random()-.5)*1.2;m.userData={b:m.position.clone(),r:m.rotation.z,p:Math.random()*6};claws.push(m);S.add(m);}
