const sp=[];for(let i=0;i<160;i++)sp.push(-6+Math.random()*12,6+Math.random()*10,-3+Math.random()*4);
const spg=new THREE.BufferGeometry().setAttribute('position',new THREE.Float32BufferAttribute(sp,3));
const spm=new THREE.Points(spg,new THREE.PointsMaterial({color:0xffffff,size:.25}));S.add(spm);
