const cap=new THREE.Mesh(new THREE.ConeGeometry(4.6,3.1,7),new THREE.MeshStandardMaterial({color:0xf4f1ea,flatShading:true}));cap.position.y=1.45;fuji.add(cap);
fuji.position.set(3,2.2,-27);S.add(fuji);
